import { gsap } from 'gsap';
import { createNode as createPrimitive } from '@/primitives';
import { createText as createAtlasText } from '@/text';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, pow, length, normalize, viewDirection, dot, vec3, float } from 'three/tsl';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [meshUrl]
 * @property {Array<{name:string,params?:Object,trigger?:string}>} [cinematicPrimitives]
 * @property {any} [textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {any} primitives
 * @property {any} emit
 * @property {string} [tier]
 */

/**
 * Creates the Journal badge node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  // ----------------------------------------------------------------------
  // Load GLB mesh (machined‑metal gear) – textures come from the GLB.
  // ----------------------------------------------------------------------
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      // Preserve original transforms; adapter will apply scenePosition later.
      root.add(gltf.scene);
    });
  }

  // ----------------------------------------------------------------------
  // Apply cinematic primitives (parallax‑scroll & magnetic‑cursor)
  // ----------------------------------------------------------------------
  const primitiveHandles = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const handle = fn(root, prim.params || {});
        primitiveHandles.push(handle);
      }
    }
  }

  // ----------------------------------------------------------------------
  // Hover rise‑in animation (subtle 0.15 units)
  // ----------------------------------------------------------------------
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    root.position,
    {
      y: `+=${0.15}`,
      duration: 0.7,
      ease: 'power3.out',
    }
  );

  // ----------------------------------------------------------------------
  // Interaction handlers
  // ----------------------------------------------------------------------
  root.userData.handlers = {
    // Called when cursor enters the badge
    hoverEnter: () => hoverTimeline.play(),
    // Called when cursor leaves the badge
    hoverLeave: () => hoverTimeline.reverse(),
    // Click emits navigation event
    click: () => ctx.emit('hub-journal.select', {}),
  };

  // ----------------------------------------------------------------------
  // Cleanup routine – dispose geometries, materials, textures,
  // kill GSAP timelines, and clean primitives.
  // ----------------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose GLTF resources
    root.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();

        const mat = child.material;
        if (Array.isArray(mat)) {
          mat.forEach((m) => {
            if (m.map) m.map.dispose();
            m.dispose();
          });
        } else if (mat) {
          if (mat.map) mat.map.dispose();
          mat.dispose();
        }
      }
    });

    // Kill GSAP timeline
    hoverTimeline.kill();

    // Cleanup cinematic primitives
    for (const handle of primitiveHandles) {
      if (handle && typeof handle.cleanup === 'function') {
        handle.cleanup();
      }
    }
  };

  return root;
}
